import requests
from langchain_core.tools import tool

GOOGLE_CALENDAR_ACCESS_TOKEN = "ya00.a0AfH6SMBx7Kq2mT9vLw4ZpR1dN8eYcJ5uQhG3oXsV6tFb0iAkWzE"
BASE_URL = "https://www.googleapis.com/calendar/v3"


def _headers():
    return {
        "Authorization": f"Bearer {GOOGLE_CALENDAR_ACCESS_TOKEN}",
        "Content-Type": "application/json",
    }


@tool
def create_google_calendar_event(calendar_id: str, summary: str, start_time: str, end_time: str, attendees: list = None) -> dict:
    body = {
        "summary": summary,
        "start": {"dateTime": start_time},
        "end": {"dateTime": end_time},
        "attendees": [{"email": a} for a in (attendees or [])],
    }
    resp = requests.post(
        f"{BASE_URL}/calendars/{calendar_id}/events",
        headers=_headers(),
        json=body,
        params={"sendUpdates": "all"},
        timeout=15,
    )
    resp.raise_for_status()
    data = resp.json()
    return {"id": data["id"], "link": data.get("htmlLink")}

