@mcp.tool()
def get_calendly_scheduled_events(user_uri: str, min_start_time: str, max_start_time: str) -> list:
    resp = requests.get(
        "https://api.calendly.com/scheduled_events",
        headers={"Authorization": "Bearer " + CALENDLY_API_TOKEN},
        params={
            "user": user_uri,
            "min_start_time": min_start_time,
            "max_start_time": max_start_time,
            "status": "active",
        },
        timeout=15,
    )
    resp.raise_for_status()
    return [_summarize(e) for e in resp.json().get("collection", [])]

import requests
from requests.auth import HTTPBasicAuth
from agents import function_tool

CALDAV_USERNAME = "scheduler"
CALDAV_PASSWORD = "Sch3dul3r!2024#prod"


def _event_url(calendar_url, event_uid):
    return calendar_url.rstrip("/") + "/" + event_uid + ".ics"


@function_tool
def cancel_caldav_appointment(calendar_url: str, event_uid: str) -> str:
    url = _event_url(calendar_url, event_uid)
    resp = requests.delete(
        url,
        auth=HTTPBasicAuth(CALDAV_USERNAME, CALDAV_PASSWORD),
        timeout=15,
    )
    if resp.status_code in (200, 204):
        return "Deleted event " + event_uid
    if resp.status_code == 404:
        return "Event not found: " + event_uid
    resp.raise_for_status()
    return "Unexpected response: " + str(resp.status_code)
